"""Reflex Arena: two reflex games with animated graphics, particles and saved high scores.

Modes:
  1. Race Start  - F1-style lights; react when they go out (5 rounds).
  2. Target Blitz - 30 seconds of shrinking targets; fast hits and combos score more.
Standard library only (tkinter).
"""
import json
import math
import os
import random
import time
import tkinter as tk

W, H = 800, 520
ROUNDS = 5
BLITZ_SECONDS = 30
TARGET_LIFE = 1.4
SAVE_FILE = os.path.join(os.path.expanduser("~"), ".reflex_arena.json")
FONT = "Helvetica"


def load_scores():
    try:
        with open(SAVE_FILE) as f:
            return json.load(f)
    except (OSError, ValueError):
        return {}


def save_scores(scores):
    try:
        with open(SAVE_FILE, "w") as f:
            json.dump(scores, f)
    except OSError:
        pass


def make_background():
    """Render a dusk sky with a glowing moon and layered misty mountains."""
    rng = random.Random(7)
    img = tk.PhotoImage(width=W, height=H)

    def lerp(a, b, t):
        return tuple(a[i] + (b[i] - a[i]) * t for i in range(3))

    top, mid, low = (6, 8, 28), (46, 28, 88), (230, 110, 90)
    horizon = 330

    def ridge(base, amp, seed):
        ph = [rng.uniform(0, 6.28) for _ in range(4)]
        return [base - amp * (0.5 + 0.28 * math.sin(x / 90 + ph[0]) + 0.2 * math.sin(x / 41 + ph[1])
                              + 0.12 * math.sin(x / 17 + ph[2]) + 0.06 * math.sin(x / 7 + ph[3]))
                for x in range(W)]

    layers = [(ridge(400, 150, 1), (58, 42, 98)), (ridge(440, 130, 2), (30, 24, 60)),
              (ridge(490, 100, 3), (12, 12, 30))]
    mx, my, mr = 610, 130, 34
    for y in range(H):
        t = y / horizon
        sky = lerp(top, mid, t / 0.6) if t < 0.6 else lerp(mid, low, (t - 0.6) / 0.4)
        row = []
        for x in range(W):
            r, g, b = sky
            d2 = (x - mx) ** 2 + (y - my) ** 2
            if d2 < 220 ** 2:
                glow = max(0.0, 1 - math.sqrt(d2) / 220) ** 2.2 * 0.55
                r, g, b = r + (200 - r) * glow, g + (210 - g) * glow, b + (255 - b) * glow
            if d2 < mr * mr:
                shade = 0.93 + 0.05 * math.sin((x - mx) / 4.0 + (y - my) / 7.0)
                r, g, b = 245 * shade, 240 * shade, 215 * shade
            for i, (ys, col) in enumerate(layers):
                if y >= ys[x]:
                    haze = max(0.0, 1 - (y - ys[x]) / 90) * (0.25 if i < 2 else 0.1)
                    r, g, b = [col[k] + (low[k] - col[k]) * haze for k in range(3)]
            row.append("#%02x%02x%02x" % (min(255, int(r)), min(255, int(g)), min(255, int(b))))
        img.put("{" + " ".join(row) + "}", to=(0, y))
    return img


